import json
path="plans/2026.10.13-№1-VAULTER-KERNEL/artifacts/P2.5/review-grok.jsonl"
# extract assistant final text and bash commands that look like the finding reproductions
n=0
last_text=None
cmds=[]
with open(path) as f:
    for line in f:
        n+=1
        try:
            o=json.loads(line)
        except Exception:
            continue
        msg=o.get("message") or {}
        if msg.get("role")=="assistant":
            content=msg.get("content") or []
            texts=[]
            for c in content:
                if isinstance(c, dict) and c.get("type")=="text":
                    texts.append(c.get("text",""))
                if isinstance(c, dict) and c.get("type")=="tool_use" and c.get("name") in ("run_terminal_command","bash"):
                    inp=c.get("input") or {}
                    cmd=inp.get("command","")
                    if cmd:
                        cmds.append((n, cmd[:400].replace("\n"," | ")))
            if texts:
                last_text="\n".join(texts)
print("lines", n, "cmds", len(cmds))
print("--- LAST TEXT LEN", len(last_text or ""))
print((last_text or "")[:8000])
print("--- TAIL CMDS ---")
for i,c in cmds[-8:]:
    print(i, c[:300])
    print("---")
