import json, pathlib
arch=json.load(open("plans/2026.10.13-№1-VAULTER-KERNEL/knowledge/architecture.json"))
for s in arch["sections"]:
    if s["id"] in ("kernel","packages"):
        print("\n==========", s["id"], "len", len(s["text"]))
        for i,line in enumerate(s["text"].splitlines()):
            if any(k in line for k in ("Label","Icon","presentation","HasLabel","kernel","Attributes")):
                print(f"{i:04d}| {line[:400]}")

print("\n\n===== DECISIONS D21-D31 =====")
dec=pathlib.Path("plans/2026.10.13-№1-VAULTER-KERNEL/decisions")
for name in ["D21","D22","D23","D24","D25","D26","D27","D28","D29","D30","D31","D32","D33","D34","D6"]:
    p=dec/f"{name}.json"
    if not p.exists():
        print(name, "MISSING")
        continue
    d=json.load(open(p))
    blob=json.dumps(d, ensure_ascii=False)
    hits=[k for k in ("Label","Icon","HasLabel","HasIcon","EnumCase","presentation","BlobStatus") if k in blob]
    print(f"\n== {name} status={d.get('status')} applies={d.get('applies_to')} hits={hits}")
    print("title:", d.get("title"))
    q=d.get("question") or ""
    print("question:", q[:500])
    # options ids
    opts=d.get("options") or []
    if isinstance(opts, list):
        for o in opts:
            if isinstance(o, dict):
                print(f"  opt {o.get('id')}: {str(o.get('text') or o.get('label') or '')[:220]}")
    decs=d.get("decision") or d.get("answer") or d.get("choice")
    if decs:
        print("decision:", str(decs)[:400])
